<?php require_once __DIR__.'/database.php';class AuthModel{private PDO $db;function __construct(){$this->db=Database::get();}function byEmail($e){$s=$this->db->prepare('SELECT * FROM users WHERE email=?');$s->execute([$e]);return $s->fetch()?:null;}function byId($id){$s=$this->db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;}function register($n,$e,$p,$pw){$s=$this->db->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?, 'patient')");return $s->execute([$n,$e,$p,password_hash($pw,PASSWORD_DEFAULT)]);}function update($id,$n,$e,$p){$s=$this->db->prepare('UPDATE users SET name=?,email=?,phone=? WHERE id=?');return $s->execute([$n,$e,$p,$id]);}function password($id,$pw){$s=$this->db->prepare('UPDATE users SET password=? WHERE id=?');return $s->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);}}
?>